namespace SstvVPrinter.IppProbe.Ipp;

public readonly record struct IppVersion(byte Major, byte Minor);
public sealed class IppMessage : IEquatable<IppMessage> { public IppMessage(IppVersion version, ushort code, int requestId, IReadOnlyList<IppAttributeGroup> groups) { Version = version; Code = code; RequestId = requestId; Groups = groups.ToArray(); } public IppVersion Version { get; } public ushort Code { get; } public int RequestId { get; } public IReadOnlyList<IppAttributeGroup> Groups { get; } public IppAttribute? FindAttribute(string name) => Groups.SelectMany(g => g.Attributes).FirstOrDefault(a => a.Name == name); public string GetRequiredString(string name) => FindAttribute(name)?.Values.FirstOrDefault()?.AsString() ?? throw new IppProtocolException($"Missing '{name}'.", IppStatusCodes.ClientErrorBadRequest); public bool Equals(IppMessage? o) => o is not null && Version == o.Version && Code == o.Code && RequestId == o.RequestId && Groups.SequenceEqual(o.Groups); public override bool Equals(object? o) => Equals(o as IppMessage); public override int GetHashCode() => Groups.Aggregate(HashCode.Combine(Version, Code, RequestId), HashCode.Combine); }
